#pragma once
#include "professional_outcome_read.hpp"
namespace hanmo::resident::professional_codec {
template<class A>Status outcome_ref(A&a,OutcomeFactRef&v){a.field("source_domain",v.source_domain);Integer kind=static_cast<Integer>(v.source_kind);a.field("source_kind",kind);if(kind<0||kind>=23)return a.reject("UnknownProfessionalOutcomeKind");if(a.reading())v.source_kind=static_cast<ProfessionalOutcomeKind>(kind);a.field("fact_id",v.fact_id);return a.field("version",v.version);}
template<class A>Status target(A&a,ProfessionalTargetRef&v){Integer kind=v.index();a.field("kind",kind);if(kind<0||kind>=8)return a.reject("UnknownProfessionalTargetKind");if(a.reading()){switch(kind){case 0:v=ProfessionalActorTarget{};break;case 1:v=ProfessionalItemTarget{};break;case 2:v=ProfessionalSiteTarget{};break;case 3:v=ProfessionalWorkTarget{};break;case 4:v=ProfessionalCaseTarget{};break;case 5:v=ProfessionalBatchTarget{};break;case 6:v=ProfessionalRitualTarget{};break;case 7:v=ProfessionalExpeditionTarget{};break;}}return std::visit([&](auto&x){using T=std::decay_t<decltype(x)>;if constexpr(std::is_same_v<T,ProfessionalActorTarget>)return a.field("actor_id",x.actor_id);else if constexpr(std::is_same_v<T,ProfessionalItemTarget>)return a.field("instance_id",x.instance_id);else if constexpr(std::is_same_v<T,ProfessionalSiteTarget>)return a.field("site_id",x.site_id);else if constexpr(std::is_same_v<T,ProfessionalWorkTarget>)return a.field("work_id",x.work_id);else if constexpr(std::is_same_v<T,ProfessionalCaseTarget>)return a.field("case_id",x.case_id);else if constexpr(std::is_same_v<T,ProfessionalBatchTarget>)return a.field("batch_id",x.batch_id);else if constexpr(std::is_same_v<T,ProfessionalRitualTarget>)return a.field("ritual_id",x.ritual_id);else return a.field("expedition_id",x.expedition_id);},v);}
}
